public class GameMain extends Game {
    public int coins;
    public int totalCoins;
    public boolean won;
    public GameObject player;

    @Override public void onCreate() {
        build();
    }

    @Override public void onUpdate(double delta) {
        if (input.isKeyPressed(Keys.R)) build();
    }

    private void block(double x, double y) {
        GameObject crate = createObject("Crate").setPosition(x, y);
        crate.addComponent(new Sprite(Assets.CRATE, 32, 32));
        crate.addComponent(new Collider2D(32, 32));
    }

    private void coin(double x, double y) {
        totalCoins++;
        GameObject coin = createObject("Coin").setPosition(x, y);
        coin.addComponent(new Sprite(Assets.COIN, 24, 24));
        coin.addComponent(new CircleCollider2D(10).asTrigger());
        coin.addComponent(new CoinPickup());
    }

    private void slime(double x, double minX, double maxX) {
        GameObject slime = createObject("Slime").setPosition(x, 332);
        slime.addComponent(new Sprite(Assets.SLIME, 28, 28));
        slime.addComponent(new CircleCollider2D(12));
        slime.addComponent(new PatrolSlime(minX, maxX, 40));
    }

    private void build() {
        for (GameObject o : new java.util.ArrayList<>(getObjects())) o.destroy();
        won = false; coins = 0; totalCoins = 0;
        setWorldBounds(0, 0, 1568, 480);

        GameObject ground = createObject("Ground");
        TileMap map = ground.addComponent(new TileMap(Assets.GRASS, 32));
        for (int c = 0; c < 49; c++)
            for (int r = 11; r < 15; r++)
                map.setTile(c, r, r == 11 ? Assets.GRASS : Assets.DIRT);

        GameObject floor = createObject("Floor").setPosition(784, 400);
        floor.addComponent(new Collider2D(1568, 96));

        for (int i = 0; i < 4; i++) block(320 + i * 32, 304);
        block(608, 288); block(640, 288);
        for (int i = 0; i < 3; i++) block(896 + i * 32, 240);
        block(1184, 288);

        coin(360, 256); coin(624, 240); coin(928, 192); coin(1184, 240); coin(1400, 320);

        slime(500, 440, 580);
        slime(1000, 950, 1100);

        GameObject chest = createObject("Chest").setPosition(1500, 328);
        chest.addComponent(new Sprite(Assets.CHEST, 32, 32));
        chest.addComponent(new CircleCollider2D(14).asTrigger());
        chest.addComponent(new GoalChest());

        player = createObject("Player").setPosition(60, 300);
        player.addComponent(new Sprite(Assets.PLAYER01, 32, 32));
        player.addComponent(new Collider2D(20, 28));
        player.addComponent(new PlatformerCharacterController2D());
        player.addComponent(new PlayerControls());

        GameObject camera = createObject("Camera");
        camera.addComponent(new Camera2D()).follow(player);
    }

    public void respawn() {
        player.setPosition(60, 300);
        player.getComponent(CharacterController2D.class).velocity.x = 0;
        player.getComponent(CharacterController2D.class).velocity.y = 0;
    }

    @Override public void onDrawUI() {
        canvas.drawText("Monety: " + coins + "/" + totalCoins + "   A/D ruch  SPACE skok  SHIFT bieg", 320, 18, 16, "#ffd54f", "center", "middle");
        if (won) canvas.drawText("WYGRANA! Wcisnij R aby zagrac ponownie", 320, 60, 24, "#7cfc90", "center", "middle");
    }
}

