public class PlayerControls extends Component {
    @Override public void onUpdate(double delta) {
        PlatformerCharacterController2D body = requireComponent(PlatformerCharacterController2D.class);
        double x = (getGame().input.isKeyDown(Keys.D) || getGame().input.isKeyDown(Keys.RIGHT) ? 1 : 0)
                 - (getGame().input.isKeyDown(Keys.A) || getGame().input.isKeyDown(Keys.LEFT) ? 1 : 0);
        if (getGame().input.isKeyDown(Keys.SHIFT)) body.run(x); else body.walk(x);
        if ((getGame().input.isKeyPressed(Keys.SPACE) || getGame().input.isKeyPressed(Keys.W) || getGame().input.isKeyPressed(Keys.UP)) && body.isGrounded())
            body.jump();
        if (transform.y > 470) ((GameMain) getGame()).respawn();
    }

    @Override public void onCollision(GameObject other) {
        if (other.hasComponent(PatrolSlime.class)) {
            CharacterController2D body = getComponent(CharacterController2D.class);
            if (body.velocity.y > 60 && transform.y < other.transform.y - 8) {
                other.destroy();
                transform.y -= 12;
            } else {
                ((GameMain) getGame()).respawn();
            }
        }
    }
}

