public class CoinPickup extends Component {
    @Override public void onTrigger(GameObject other) {
        if (!other.hasComponent(PlayerControls.class)) return;
        ((GameMain) getGame()).coins++;
        getGame().audio.playNote("E6", 0.15, "square");
        gameObject.destroy();
    }
}

