public class PatrolSlime extends Component {
    public double minX, maxX, speed, dir = 1;
    public PatrolSlime(double minX, double maxX, double speed) { this.minX = minX; this.maxX = maxX; this.speed = speed; }
    @Override public void onUpdate(double delta) {
        transform.x += dir * speed * delta;
        if (transform.x > maxX) { transform.x = maxX; dir = -1; }
        if (transform.x < minX) { transform.x = minX; dir = 1; }
        Sprite sprite = getComponent(Sprite.class);
        if (sprite != null) sprite.flipX = dir < 0;
    }
}

